namespace sv_ae959f6950424d71b471d2a087dafadc.Services;

public class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D")
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace sv_ae959f6950424d71b471d2a087dafadc.Services;

public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;
    private int _lastLowStockCount;

    public int LastLowStockCount => _lastLowStockCount;

    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning a random low-stock count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Start polling. Uses reference counting so multiple subscribers
    /// share a single polling loop.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(_pollCts.Token);
        }
    }

    /// <summary>
    /// Stop polling when a subscriber leaves. Polling only fully stops
    /// when all subscribers have unsubscribed.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(10), ct);
                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async Task RefreshAsync()
    {
        _lastLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        OnAlertCountChanged?.Invoke();
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh when the warehouse changes
        await RefreshAsync();
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
        OnAlertCountChanged = null;
    }
}

