@using sv_ae959f6950424d71b471d2a087dafadc.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Warehouse:</label>
    <select id="warehouseSelect" class="form-select form-select-sm d-inline-block w-auto"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            WarehouseState.SetWarehouse(warehouseId);
        }
    }

    public void Dispose()
    {
        // No subscriptions to clean up here; this component only writes state
    }
}

